use vstd::prelude::*;

verus! {
    // Reverse a vector of f32's.
    // For every index i in [0, n), result[i] == m[n-1-i].
    fn numpy_flip(m: Vec<f32>) -> (result: Vec<f32>)
        ensures
            result.len() == m.len(),
            forall |i: usize| i < m.len() ==> result[i] == m[m.len() - 1 - i],
    {
        let n: usize = m.len();
        // Build a new vector by pushing elements from the back of `m`.
        let mut result: Vec<f32> = Vec::with_capacity(n);
        let mut i: usize = 0;
        while i < n
            invariant
                // loop index stays in bounds
                i <= n,
                // result has exactly `i` elements so far
                result.len() == i,
                // for all j < i, result[j] == m[n-1-j]
                forall |j: usize| j < i ==> result[j] == m[n - 1 - j],
            decreases n - i,
        {
            let x: f32 = m[n - 1 - i];
            result.push(x);
            i = i + 1;
        }
        result
    }
}

